/* Fixed current-map fold witness. No changed state, extrapolated evolution,
 * quadrature refinement, weight solve, or assumed event-box midpoint. */
#define GFS_CURVED_BRANCH_LIBRARY
#include "test_curved_branch_v1.cpp"
static curved_events::System system_for(const std::vector<curved_partition::Site> &site,const std::vector<R> &w,int i,int j){auto p=curved_events::plane(site,w,i,j);p.n[0]=I(site[j].x-site[i].x);p.n[1]=I(site[j].y-site[i].y);p.c=I((site[j].x*site[j].x+site[j].y*site[j].y-site[i].x*site[i].x-site[i].y*site[i].y+w[i]-w[j])/2);return {p,{},true};}
int main(int argc,char **argv){
    int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);active_mpi=true;need(argc==6,"same packet sites guard new output triangle");auto p=curved::read(argv[1]);auto site=curved_partition::read_sites(argv[2]);auto weight=read_weights(argv[3],site);size_t it=atoi(argv[5]);need(it==225 || it==137,"two preserved geometry witnesses");const auto &r=p.record[it];auto fixed=curved_branches::fixed_map(r,p.parameters[3]);curved_events::Context context(r,p.parameters[3],site,weight,0,0);for(int k=0;k<2;k++){for(int a=0;a<10;a++)context.map.position[k].a[a]=I(fixed.position[k][a]);for(int j=0;j<2;j++)context.map.position_B[k][j]=I(fixed.B[k][j]);}
    int i=it==225?14:8,j=it==225?15:7;auto equation=system_for(site,weight,i,j);R nx=equation.a.n[0].lo,ny=equation.a.n[1].lo,c=equation.a.c.lo,n2=nx*nx+ny*ny;need(n2>0,"nondegenerate power-plane normal");R x[2]={c*nx/n2,c*ny/n2};
    for(int iteration=0;iteration<12;iteration++){curved_events::Box point;point.x[0]=I(x[0]);point.x[1]=I(x[1]);I f[2],J[2][2];curved_events::system_value(context,equation,point,f,J);R a=curved_events::mid(J[0][0]),b=curved_events::mid(J[0][1]),v=curved_events::mid(J[1][0]),d=curved_events::mid(J[1][1]),det=a*d-b*v;need(det!=0,"nondegenerate scalar fold Newton witness");R fx=curved_events::mid(f[0]),fy=curved_events::mid(f[1]),dx=(d*fx-b*fy)/det,dy=(-v*fx+a*fy)/det;x[0]-=dx;x[1]-=dy;if(fabsl(dx)+fabsl(dy)<64*LDBL_EPSILON*(1+hypotl(x[0],x[1])))break;}
    /* One fixed validation box, no box-width sweep. Krawczyk strict inclusion
     * proves a unique representative event under the recorded interval/libm
     * model; point Newton convergence alone is never used as existence. */
    R width=1e-12L;curved_events::Box box,center;for(int k=0;k<2;k++){center.x[k]=I(x[k]);box.x[k]=I(x[k]-width,x[k]+width);}I f[2],J[2][2],fc[2],unused[2][2];curved_events::system_value(context,equation,box,f,J);curved_events::system_value(context,equation,center,fc,unused);R a=curved_events::mid(J[0][0]),b=curved_events::mid(J[0][1]),v=curved_events::mid(J[1][0]),d=curved_events::mid(J[1][1]),det=a*d-b*v;need(det!=0,"fixed-box invertible midpoint derivative");R C[2][2]={{d/det,-b/det},{-v/det,a/det}};curved_events::Box K;R contraction=0;bool inside=true;
    for(int k=0;k<2;k++){K.x[k]=center.x[k];R row=0;for(int l=0;l<2;l++)K.x[k]=K.x[k]-I(C[k][l])*fc[l];for(int l=0;l<2;l++){I E(k==l);for(int z=0;z<2;z++)E=E-I(C[k][z])*J[z][l];row+=curved_bounds::absmax(E);K.x[k]=K.x[k]+E*(box.x[l]-center.x[l]);}contraction=std::max(contraction,row);inside=inside && K.x[k].lo>box.x[k].lo && K.x[k].hi<box.x[k].hi;}
    auto values=curved_events::evaluate(context.map,K,p.parameters[3]);auto jet=curved_events::projected(values,equation.a,0);I radius=curved_events::radial(K),fr=(K.x[0]*jet.d[0]+K.x[1]*jet.d[1])/radius,ftt=curved_bounds::square(K.x[1])*jet.dd[0][0]-I(2)*K.x[0]*K.x[1]*jet.dd[0][1]+curved_bounds::square(K.x[0])*jet.dd[1][1]-K.x[0]*jet.d[0]-K.x[1]*jet.d[1];bool simple=inside && contraction<1 && curved_events::excludes(fr) && curved_events::excludes(ftt),possible=curved_events::source_possible(r,K);
    std::string dest=argv[4];FILE *fout=fopen((dest+"/fold.csv").c_str(),"w");need(fout,"new fixed-map fold witness");fprintf(fout,"triangle,i,j,xlo,xhi,ylo,yhi,rlo,rhi,fr_lo,fr_hi,f_theta_theta_lo,f_theta_theta_hi,krawczyk_interior,contraction,source_possible\n%zu,%d,%d,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%d,%.21Lg,%d\n",it,i,j,K.x[0].lo,K.x[0].hi,K.x[1].lo,K.x[1].hi,radius.lo,radius.hi,fr.lo,fr.hi,ftt.lo,ftt.hi,inside,contraction,possible);fclose(fout);printf("{\"scope\":\"unique simple fold of the same fixed representative; fixed validation box, engineering interval/libm model; no physical evolution\",\"triangle\":%zu,\"plane_i\":%d,\"plane_j\":%d,\"krawczyk_interior\":%s,\"contraction\":%.17Lg,\"simple_fold\":%s,\"source_possible\":%s,\"critical_radius_lo\":%.21Lg,\"critical_radius_hi\":%.21Lg,\"full_cold_transfer_proved\":false}\n",it,i,j,inside?"true":"false",contraction,simple?"true":"false",possible?"true":"false",radius.lo,radius.hi);active_mpi=false;MPI_Finalize();return simple?0:2;
}
